{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Flupirtine, the closest analogue, had an absolute oral bioavailability of 90.0% in healthy young volunteers when a 200 mg oral dose was compared with an 80 mg IV dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Safinamide 50 mg immediate-release tablets had an absolute oral bioavailability of about 95% (90% CI 90–99%) versus IV in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Lumiracoxib 200 mg oral versus 100 mg IV had an absolute oral bioavailability of 74.0 ± 8.6% in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Tiracizine 50 mg oral had a mean systemic availability of about 34% (16–68%) in humans, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close desaza analogue of flupirtine, whose absolute oral bioavailability is 90% in humans. Additional fluorobenzylamine and aryl analogues also show high oral bioavailability (74–95%). The closest and most transferable evidence strongly supports F ≥ 20%, so the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query molecule.",
    "The closest analogue flupirtine contains a pyridine ring nitrogen that is replaced by CH in the query; the impact on solubility and first-pass metabolism is inferred rather than measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

